package com.aistock.scheduler.task;
import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;
public final class HttpPredictionTaskClient implements PredictionTaskClient {
 private final String base;private final PredictionTaskHttp http;private final Duration executeTimeout,readTimeout;
 public HttpPredictionTaskClient(String base,String token,ObjectMapper mapper){this(base,token,mapper,Duration.ofSeconds(100),Duration.ofSeconds(10));}
 HttpPredictionTaskClient(String base,String token,ObjectMapper mapper,Duration executeTimeout,Duration readTimeout){this.base=base;this.http=new PredictionTaskHttp(token,mapper);this.executeTimeout=executeTimeout;this.readTimeout=readTimeout;}
 public MarketRefreshClient.Result execute(TaskRepository.Claim c){if(!uuid(c.predictionId())||!uuid(c.attemptId()))throw invalid();try{return receipt(data(http.call(base,"/internal/v1/predictions/"+c.predictionId()+"/verify",Map.of("operationId",c.attemptId(),"dueThrough",c.targetDate(),"leaseUntil",c.leaseUntil()),executeTimeout)),c);}catch(PredictionTaskHttp.Remote e){if(MarketUseTaskErrors.definitive(e.status,e.code))return new MarketRefreshClient.Result(c.attemptId(),"FAILED",null,e.code);String code=switch(e.code){case "RESOURCE_NOT_FOUND"->"VERIFICATION_PREDICTION_INVALID";case "VERIFICATION_REQUEST_INVALID","VERIFICATION_PREDICTION_INVALID","VERIFICATION_RECORD_INVALID"->e.code;case "AUTH_REQUIRED","ACCESS_DENIED"->"VERIFICATION_ACCESS_DENIED";default->null;};if(code!=null&&e.status>=400&&e.status<500)return new MarketRefreshClient.Result(c.attemptId(),"FAILED",null,code);throw e;}}
 public MarketRefreshClient.Result receipt(TaskRepository.Claim c){if(!uuid(c.attemptId()))throw invalid();try{return receipt(data(http.call(base,"/internal/v1/prediction-verifications/operations/"+c.attemptId(),null,readTimeout)),c);}catch(PredictionTaskHttp.Remote e){if(e.status==404&&e.code.equals("RESOURCE_NOT_FOUND"))throw new MissingReceipt();throw e;}}
 public Page due(LocalDate cutoff,String after){if(cutoff==null||after!=null&&!uuid(after))throw invalid();var path="/internal/v1/prediction-verifications/due?dueThrough="+cutoff+"&limit=50"+(after==null?"":"&after="+after);return parsePage(data(http.call(base,path,null,readTimeout)),cutoff,after);}
 static Page parsePage(JsonNode node,LocalDate cutoff,String after){try{if(!cutoff.toString().equals(node.path("cutoffDate").asText())||!node.path("items").isArray()||node.path("items").size()>50)throw invalid();var items=new ArrayList<Item>();String previous=after==null?"":after;for(var n:node.path("items")){String id=n.path("predictionId").asText(),stock=n.path("instrumentId").asText(),rule=n.path("ruleVersion").asText();LocalDate due=LocalDate.parse(n.path("dueThrough").asText());if(!uuid(id)||id.compareTo(previous)<=0||!stock.matches("(SH|SZ)[0-9]{6}")||!"origin-share-close-v1".equals(rule)||due.isBefore(LocalDate.of(1990,1,1))||due.isAfter(cutoff))throw invalid();items.add(new Item(id,stock,due,rule));previous=id;}String next=node.path("nextCursor").isNull()?null:node.path("nextCursor").asText();if(next!=null&&(!uuid(next)||items.isEmpty()||!next.equals(previous)))throw invalid();return new Page(cutoff,items,next);}catch(PredictionTaskHttp.Remote e){throw e;}catch(Exception e){throw invalid();}} private MarketRefreshClient.Result receipt(JsonNode n,TaskRepository.Claim c){String op=n.path("operationId").asText(),state=n.path("state").asText();String version=n.path("versionId").isNull()?null:n.path("versionId").asText();String error=n.path("errorCode").isNull()?null:n.path("errorCode").asText();if(!c.attemptId().equals(op)||!Set.of("AVAILABLE","FAILED","RUNNING","SKIPPED_NOT_DUE").contains(state))throw invalid();if(state.equals("AVAILABLE")){if(!uuid(version)||error!=null)throw invalid();}else if(version!=null)throw invalid();if(state.equals("FAILED")){if(error==null||!error.matches("[A-Z0-9_]{1,64}"))throw invalid();}else if(error!=null)throw invalid();return new MarketRefreshClient.Result(op,state,version,error);}
 private JsonNode data(JsonNode node){if(!"OK".equals(node.path("code").asText())||!node.path("data").isObject())throw invalid();return node.path("data");}
 static boolean uuid(String value){return value!=null&&value.matches("[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}");}
 static PredictionTaskHttp.Remote invalid(){return new PredictionTaskHttp.Remote(-1,"VERIFICATION_SOURCE_INVALID");}
}
